<?php
declare(strict_types=1);namespace App\Command;use App\Imperium\Runtime\Curia\OperationalReturnAuthorizationService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Input\InputOption;use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:curia:authorize-operational-return',description:'Authorize return, retirement, unbinding, and custody restoration after one completed bounded execution.')]
final class CuriaAuthorizeOperationalReturnCommand extends Command{public function __construct(private readonly OperationalReturnAuthorizationService$s){parent::__construct();}protected function configure():void{$this->addArgument('execution-id',InputArgument::REQUIRED)->addArgument('seneschal-binding-id',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface$i,OutputInterface$o):int{try{$r=$this->s->authorize((string)$i->getArgument('execution-id'),(string)$i->getArgument('seneschal-binding-id'));}catch(\Throwable$e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}$o->writeln($i->getOption('json')?json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR):'<info>OPERATIONAL_RETURN_AUTHORIZED</info> '.$r['authorization_id']);return self::SUCCESS;}}
